const url=v=>{try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return''}};
const operationLabel=v=>({connection_check:'连接检查',xiantao_class_area_2021:'仙桃2021分类面积',native_class_statistics:'原生分类统计',bounded_ndvi:'有界NDVI计算',bounded_delta_ndvi:'有界指数变化',current_model_forecast:'气象模型读取',city_mask:'参考市界掩膜',reference_overlay:'参考要素叠加',catalog_search:'目录检索',stac_search:'STAC目录检索',read_cog_window:'COG有界窗口读取',ndvi:'NDVI计算',ndvi_change:'两期指数变化',landcover_area:'分类面积核算',weather_forecast:'气象模型读取',vector_analysis:'矢量空间分析',spatial_summary:'空间统计',nearest:'最近邻分析',user_import:'用户数据导入'}[v]||(typeof v==='string'&&v.startsWith('bounded_delta_')?'有界'+v.slice(14).toUpperCase()+'变化':typeof v==='string'&&v.startsWith('bounded_')?'有界'+v.slice(8).toUpperCase()+'计算':v));
function stageText(v){return({not_configured:'待配置 Key',configured:'已配置 · 待验证',verified:'验证通过',partial:'部分服务可用',failed:'验证未通过',restricted:'调用受限',adapter_ready_on_demand:'按需调用适配',planned_not_connected:'规划，尚未连接',authorization_pending:'授权待确认',registered_not_connected:'仅登记，未连接',planned:'规划阶段',authorization_required:'待授权',pending_authorization:'待授权',available:'条件可用',implemented:'适配已实现',operational:'已有执行适配',catalog_only:'仅目录可检索',local:'本地可用',connected:'已有适配',requires_account:'需要服务账户'}[v]||v||'接入阶段待确认')}
export class SourcesWorkspace{
 constructor({api,toast,showDialog,onDatasets,onProfessional,onIntegrationChange,onBoundary,onPrepareAnalysis,onObservationMap,onImport,onDatasetMap}){this.api=api;this.toast=toast;this.onImport=onImport;this.onDatasetMap=onDatasetMap;this.datasets=[];this.datasetsReady=false;this.datasetsLoading=false;this.datasetsError='';this.showDialog=showDialog;this.onDatasets=onDatasets;this.onProfessional=onProfessional;this.onIntegrationChange=onIntegrationChange;this.onBoundary=onBoundary;this.onPrepareAnalysis=onPrepareAnalysis;this.onObservationMap=onObservationMap;this.library=null;this.ingestBusy=false;this.ingestedSearches=new Set();this.tianditu=null;this.adminQuery='';this.adminResults=[];this.adminSuggestions=[];this.adminError='';this.adminBusy=false;this.element=document.createElement('section');this.element.className='sources-workspace';this.sources=[];this.searches=[];this.plans=[];this.plan=null;this.searchResult=null;this.tab='uploads';this.filter='all';this.query='';this.ready=false;this.loading=false;this.error='';this.searchBusy=false;this.planBusy=false;this.searchDraft={source_ids:['pc_sentinel2_l2a'],bbox:'112.922,30.094,113.832,30.537',start:'2025-10-01',end:'2025-11-30',limit:3};this.planDraft={question:'分析仙桃全市耕地面积，说明适合的数据来源、年度边界与后续缺口。',region:'',bbox:'',start:'',end:'',goal:''};this.bind();document.addEventListener('click',async e=>{const b=e.target.closest('#dialog [data-sw-action]');if(!b||b.disabled)return;try{b.disabled=true;await this.act(b.dataset.swAction,b)}catch(err){this.toast(err.message)}finally{if(b.isConnected)b.disabled=false}});this.render()}
 bind(){this.element.addEventListener('click',async e=>{const b=e.target.closest('[data-sw-action]');if(!b||b.disabled)return;try{b.disabled=true;await this.act(b.dataset.swAction,b)}catch(err){this.error=err.message;this.toast(err.message);this.render()}finally{if(b.isConnected)b.disabled=false}});this.element.addEventListener('input',e=>{const el=e.target;if(el.id==='sw-catalog-search'){this.query=el.value;this.renderCards()}if(el.dataset.searchField)this.searchDraft[el.dataset.searchField]=el.value;if(el.dataset.planField)this.planDraft[el.dataset.planField]=el.value});this.element.addEventListener('change',async e=>{if(e.target.id==='sw-search-history'&&e.target.value){try{this.searchResult=await this.api('/data-searches/'+encodeURIComponent(e.target.value));this.render()}catch(err){this.toast(err.message)}}if(e.target.id==='sw-plan-history'&&e.target.value){try{this.plan=await this.api('/data-plans/'+encodeURIComponent(e.target.value));this.render()}catch(err){this.toast(err.message)}}if(e.target.dataset.sourceSearch){const id=e.target.dataset.sourceSearch;this.searchDraft.source_ids=e.target.checked?[...new Set([...this.searchDraft.source_ids,id])]:this.searchDraft.source_ids.filter(x=>x!==id)}})}
 async mount(host){host.replaceChildren(this.element);this.render();if(!this.ready&&!this.loading)await this.load();else await Promise.all([this.loadTianditu(),this.refreshDatasets()])}
 async load(){this.loading=true;this.error='';this.render();try{const [catalog,searches,plans]=await Promise.all([this.api('/data-sources'),this.api('/data-searches'),this.api('/data-plans'),this.refreshDatasets(false)]);this.sources=catalog.sources||[];this.searches=searches;this.plans=plans;this.ready=true;await this.loadTianditu(false)}catch(e){this.error=e.message}finally{this.loading=false;this.render()}}
 async refreshDatasets(render=true){this.datasetsLoading=true;this.datasetsError='';if(render)this.render();try{const data=await this.api('/datasets');if(!Array.isArray(data))throw Error('上传数据目录格式无效，请重新加载');this.datasets=data.filter(d=>d.source_type==='user');this.datasetsReady=true;return this.datasets}catch(error){this.datasetsError=error.message||'上传数据目录暂未连接';return this.datasets}finally{this.datasetsLoading=false;if(render)this.render()}}
 geometryLabel(types){const labels={Point:'点',LineString:'线',Polygon:'面',MultiPolygon:'多面'};return Object.entries(types||{}).map(([kind,count])=>(labels[kind]||kind)+' '+count).join(' · ')||'类型见数据详情'}
 uploadsView(){return `<section class="sw-uploads"><div class="sw-upload-intro"><div><h2>我的数据</h2><p>上传后直接上图，可查看点位、线路、地块和原始属性。</p></div><div>${this.button('刷新列表','reload-uploads','refresh','',this.datasetsLoading?'disabled':'')}</div></div><div class="sw-upload-format">${icon('info')}支持 WGS84 GeoJSON FeatureCollection：点、线、面与多面，单文件最多500个要素 / 2 MB，坐标顺序为[经度, 纬度]。Excel、CSV、Shapefile和GeoTIFF暂不能在此直接上传。</div>${this.datasetsError?`<div class="sw-upload-error" role="alert">${esc(this.datasetsError)}${this.button('重新加载','reload-uploads','refresh')}</div>`:''}${this.datasetsLoading&&!this.datasetsReady?'<div class="sw-loading"><span class="mc-spinner"></span>正在读取已上传数据…</div>':this.datasets.length?`<div class="sw-upload-grid">${this.datasets.map(d=>`<article class="sw-upload-card"><div class="sw-upload-card-heading"><span class="sw-upload-mark">${icon('layers')}</span><div><h3>${esc(d.name)}</h3><p>用户上传 · WGS84 · v${esc(d.version||1)}</p></div><span class="sw-upload-count">${esc(d.feature_count)} 个要素</span></div><dl><div><dt>几何类型</dt><dd>${esc(this.geometryLabel(d.geometry_types))}</dd></div><div><dt>坐标范围</dt><dd>${esc(fmtBounds(d.bbox))}</dd></div><div><dt>上传时间</dt><dd>${esc(stamp(d.created_at))}</dd></div></dl><div class="sw-upload-card-actions">${this.button('显示到地图','dataset-map','layers','primary',`data-id="${esc(d.id)}"`)}${this.button('属性与来源','dataset-detail','info','',`data-id="${esc(d.id)}"`)}</div></article>`).join('')}</div>`:!this.datasetsLoading&&!this.datasetsError?`<div class="sw-upload-empty">${icon('layers')}<h3>还没有上传空间数据</h3><p>上传GeoJSON后即可在地图查看，无需先运行分析。</p>${this.button('上传第一份数据','upload','plus','primary')}</div>`:''}</section>`}
 async datasetDetail(id){const d=await this.api('/datasets/'+encodeURIComponent(id));if(d.source_type!=='user')throw Error('此入口仅查看用户上传数据');const features=d.geojson?.features||[],keys=[...new Set(features.flatMap(f=>Object.keys(f.properties||{})))].slice(0,5);const preview=features.slice(0,5);this.showDialog(esc(d.name),`<p>用户上传数据，保存在本机工作空间；业务属性与位置真实性由数据提供方确认。</p><div class="dialog-rows">${[['数据版本','v'+(d.version||1)],['要素数量',d.feature_count],['几何类型',this.geometryLabel(d.geometry_types)],['坐标基准','WGS84（经度, 纬度）'],['坐标范围',fmtBounds(d.bbox)],['上传时间',stamp(d.created_at)],['内容指纹 SHA256',d.sha256||'未提供']].map(([label,value])=>`<div class="dialog-row"><span>${esc(label)}</span><span>${esc(value)}</span></div>`).join('')}</div><h3 class="sw-upload-preview-heading">原始属性预览</h3><p>展示前${preview.length}个要素及最多5个字段；完整属性可在地图点击要素查看。</p><div class="sw-upload-attribute-table"><table><thead><tr><th>要素ID</th>${keys.map(key=>`<th>${esc(key)}</th>`).join('')}</tr></thead><tbody>${preview.map(f=>`<tr><td>${esc(f.id??'—')}</td>${keys.map(key=>`<td>${esc(f.properties?.[key]===null?'空值':f.properties?.[key]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,this.button('显示到地图','dataset-map','layers','primary',`data-id="${esc(d.id)}"`))}
 button(n,a,i='arrow',cls='',extra=''){return `<button class="sw-button ${cls}" data-sw-action="${a}" ${extra}>${icon(i)}<span>${n}</span></button>`}
 raster(s){if(typeof s.stages?.pixel_applicable==='boolean')return s.stages.pixel_applicable;return /sentinel|landsat|worldcover|raster|optical|sar|dem|高分|影像/i.test(s.id+' '+s.source_type+' '+s.name)}
 category(s){if(s.id.startsWith('tianditu_'))return'service';if(s.id.startsWith('draft_'))return'draft';if(/worldcover|专题|landcover|product/i.test(s.id+' '+s.source_type))return'product';if(this.raster(s))return'remote';if(/weather|meteo|气象/i.test(s.id+' '+s.source_type))return'model';if(/boundary|geojson|vector|边界/i.test(s.id+' '+s.source_type))return'vector';return'pending'}
 filtered(){return this.sources.filter(s=>(this.filter==='all'||this.category(s)===this.filter||this.filter==='pending'&&!s.id.startsWith('draft_')&&!s.stages?.catalog_searchable&&!s.stages?.analysis_ready)&&(s.name+' '+s.provider+' '+s.source_type+' '+(s.semantics||[]).join(' ')).toLowerCase().includes(this.query.toLowerCase()))}
 render(){const cat=this.sources,implemented=cat.filter(s=>yes(s.stages?.catalog_searchable)).length,analyzable=cat.filter(s=>yes(s.stages?.analysis_ready)).length,pending=cat.filter(s=>s.id.startsWith('tianditu_')?!s.stages?.service_queryable:!s.stages?.analysis_ready&&!s.stages?.catalog_searchable).length;this.element.innerHTML=`<div class="sw-heading"><div><h1>数据</h1><p>管理我的图层，查找影像和可用数据来源。</p></div><div>${this.button('上传数据','upload','plus','primary')}<details class="sw-data-settings"><summary>${icon('data')}数据设置</summary><div>${this.button('数据选源','tab','layers','', 'data-tab="plans"')}${this.button('地图服务设置','tianditu-config','data','')}${this.button('登记数据接入','draft','plus','')}</div></details></div></div><div class="sw-tabs" role="tablist"><button role="tab" class="${this.tab==='uploads'?'active':''}" aria-selected="${this.tab==='uploads'}" data-sw-action="tab" data-tab="uploads">${icon('layers')}我的数据<span>${this.datasets.length}</span></button><button role="tab" class="${this.tab==='catalog'?'active':''}" aria-selected="${this.tab==='catalog'}" data-sw-action="tab" data-tab="catalog">${icon('data')}数据来源<span>${cat.length}</span></button><button role="tab" class="${this.tab==='library'?'active':''}" aria-selected="${this.tab==='library'}" data-sw-action="tab" data-tab="library">${icon('layers')}影像资源</button><button role="tab" class="${this.tab==='search'?'active':''}" aria-selected="${this.tab==='search'}" data-sw-action="tab" data-tab="search">${icon('search')}查找影像</button></div>${this.error&&this.ready&&this.tab!=='uploads'?`<div class="sw-inline-error" role="alert">${icon('info')}${esc(this.error)}</div>`:''}${this.tab==='uploads'?this.uploadsView():this.loading&&!this.ready?'<div class="sw-loading"><span class="mc-spinner"></span>正在读取数据来源与记录…</div>':this.error&&!this.ready?`<div class="sw-error"><h2>目录服务暂未连接</h2><p>${esc(this.error)}</p>${this.button('重新连接','reload','refresh')}</div>`:this.tab==='catalog'?`${this.tiandituCard()}<div class="sw-summary-strip"><div><b>${cat.length}</b><span>已编目的数据源</span></div><div><b>${implemented}</b><span>具备目录检索适配</span></div><div><b>${analyzable}</b><span>具备既有分析适配</span></div><div><b>${pending}</b><span>待授权或待对接</span></div><p>“适配已实现”不代表本次已取得数据；<br>调用记录和数据质量以具体任务为准。</p></div><div class="sw-catalog-controls"><div>${[['all','全部来源'],['remote','遥感影像'],['product','专题产品'],['model','气象模型'],['vector','边界与要素'],['service','地图与定位'],['pending','待授权 / 规划'],['draft','接入草案']].map(([k,n])=>`<button class="${this.filter===k?'active':''}" data-sw-action="filter" data-filter="${k}">${n}</button>`).join('')}</div><label>${icon('search')}<input id="sw-catalog-search" value="${esc(this.query)}" placeholder="搜索来源、提供方或业务语义…"></label></div><div class="sw-source-grid" id="sw-source-cards">${this.cards()}</div>`:this.tab==='library'?'<div id="sw-observation-library"></div>':this.tab==='search'?this.searchView():this.planView()}`;if(this.tab==='library')this.mountLibrary()}
 cards(){return this.filtered().map(s=>this.card(s)).join('')||'<div class="sw-empty">没有匹配的数据源。可调整条件或登记新的接入草案。</div>'}
 renderCards(){const el=this.element.querySelector('#sw-source-cards');if(el)el.innerHTML=this.cards()}
 stages(s){const st=s.stages||{},raster=this.raster(s);if(s.id.startsWith('tianditu_'))return `<div class="sw-stage-matrix"><div class="ready"><small>服务适配</small><b>接口适配已实现</b></div><div class="${st.service_queryable?'ready':''}"><small>本机配置</small><b>${st.service_queryable?'已配置，可请求':'待配置 Key'}</b></div><div class="${s.verification?.status==='verified'?'ready':''}"><small>连接检查</small><b>${esc(stageText(s.verification?.status||'not_configured'))}</b></div><div><small>业务用途</small><b>${s.id==='tianditu_maps'?'地图展示':s.id==='tianditu_places'?'地点与地址定位':'行政区参考边界'}</b></div></div>`;return `<div class="sw-stage-matrix"><div class="${st.catalog_searchable?'ready':''}"><small>目录发现</small><b>${st.catalog_searchable?'可检索目录':st.pixel_readable?'固定产品直读':/geojson|boundary|weather|meteo/i.test(s.id)?'直读 / 本地目录':'尚未接入'}</b></div><div class="${st.pixel_readable?'ready':!raster?'na':''}"><small>${raster?'像素获取':'像素获取'}</small><b>${!raster?'不适用':st.pixel_readable?'有读取适配':'未接像素'}</b></div><div class="${st.analysis_ready?'ready':''}"><small>分析执行</small><b>${st.analysis_ready?'既有算法可用':'暂无执行适配'}</b></div><div><small>接入阶段</small><b>${esc(stageText(st.connection_status))}</b></div></div>`}
 card(s){const coverage=s.coverage||{},temporal=coverage.temporal||{},year=temporal.product_year,res=s.resolution||{},latest=this.latestVerification(s),isDraft=s.id.startsWith('draft_');return `<article class="sw-source-card"><div class="sw-source-card-top"><span class="sw-source-icon">${icon(this.category(s)==='remote'?'layers':this.category(s)==='model'?'clock':'data')}</span><div><span>${esc(s.provider||'提供方待确认')}</span><h2>${esc(s.name)}</h2></div><span class="sw-source-type ${isDraft?'draft':''}">${isDraft?'仅登记':this.category(s)==='pending'?'待接入':s.stages?.analysis_ready?'支持已有分析':s.stages?.catalog_searchable?'可查影像目录':s.id.startsWith('tianditu_')?esc(stageText(s.stages?.connection_status)):s.stages?.connection_status==='registered_not_connected'?'仅登记 / 未连接':'规划 / 待接入'}</span></div><div class="sw-source-range">覆盖 ${fmtBounds(s.coverage?.spatial?.bbox)} · ${esc(s.coverage?.spatial?.crs||'坐标基准见详情')}</div><p class="sw-source-semantics">${esc((s.semantics||[]).join(' · ')||'业务语义待完善')}</p><details class="sw-source-conditions"><summary>连接与数据条件</summary>${this.stages(s)}</details><div class="sw-source-facts"><div><span>数据时相</span><b>${year?esc(year)+' 固定年度':esc(temporal.start||'起始未提供')+' — '+esc(temporal.end||'持续更新 / 未提供')}</b></div><div><span>空间与分辨率</span><b>${esc(res.description||res.native||text(res.value)+' '+(res.unit||''))}</b></div><div><span>许可</span><b>${esc(s.license?.name||'待核实')}${s.license?.verified?'':' · 未核验'}</b></div><div><span>服务与授权</span><b>${esc(this.authText(s))} · ${esc(s.cost?.model==='provider_service_terms'?'按提供方服务条款':s.cost?.model==='unknown'?'费用待确认':s.cost?.model||'费用待核实')}</b></div></div><div class="sw-verification ${latest?.status==='failed'?'failed':''}"><i></i><span>${latest?`${esc(latest.label)} · ${stamp(latest.time)}${latest.count!==undefined?' · '+latest.count+' 条':''}`:'近期实测：本工作空间暂无调用证据'}</span></div><div class="sw-source-card-footer"><span>${esc(s.protocol||'协议待确认')} · ${esc(s.adapter?.version||'版本未提供')}</span><button data-sw-action="detail" data-id="${esc(s.id)}">数据详情与边界 ${icon('arrow')}</button></div></article>`}
 authText(s){if(s.id.startsWith('tianditu_'))return'需本单位应用 Key';if(!s.stages?.catalog_searchable&&!s.stages?.pixel_readable&&!s.stages?.analysis_ready)return '授权与接口待确认';return s.auth?.account_required?'需服务账户':s.auth?.user_key_required?'需用户密钥':s.auth?.kind==='public_provider_managed_sas'?'服务端临时凭据':s.auth?.kind==='none'?'无需用户密钥':s.auth?.kind||'按服务条款'}
 latestVerification(source){const v=source.verification;if(source.id.startsWith('tianditu_')&&v?.checked_at&&['verified','partial','failed'].includes(v.status))return{status:v.status,time:v.checked_at,label:'连接检查'+({verified:'通过',partial:'部分通过',failed:'失败'}[v.status])};if(v?.checked_at&&['succeeded','failed','empty'].includes(v.status))return{status:v.status,time:v.checked_at,label:(v.operation==='catalog_search'?'目录检索':operationLabel(v.operation||'实际调用'))+(v.status==='succeeded'?'成功':v.status==='empty'?'无命中':'失败')};const search=this.latestSearch(source.id);if(search)return{...search,label:search.status==='succeeded'?'目录检索成功':search.status==='empty'?'目录无命中':'目录请求失败'};for(const p of this.plans){if(p.execution_evidence?.status==='succeeded'&&(p.used||[]).some(u=>(u.source_id||u.id)===source.id))return{status:'succeeded',time:p.execution_evidence.result_created_at||p.created_at,label:'已有成功任务来源证据（仅对应任务）'}}return null}
 latestSearch(id){for(const search of this.searches){const r=search.results?.find(r=>r.source_id===id);if(r)return{status:r.status,count:r.items?.length||0,time:search.created_at}}return null}
 searchView(){const eligible=this.sources.filter(s=>s.stages?.catalog_searchable);return `<div class="sw-work-layout"><section class="sw-config-panel"><h2>查找影像</h2><p>按需检索已适配的公开STAC服务，单次最多选择7个来源。将命中记录入库后，可继续匹配波段与算法。</p><div class="sw-source-checkboxes">${eligible.map(s=>`<label><input type="checkbox" data-source-search="${esc(s.id)}" ${this.searchDraft.source_ids.includes(s.id)?'checked':''}><span>${esc(s.name)}</span></label>`).join('')||'<small>暂无支持本检索的目录适配。</small>'}</div><label class="sw-field">研究范围 bbox（西,南,东,北）<input data-search-field="bbox" value="${esc(this.searchDraft.bbox)}"></label><div class="sw-two-fields"><label class="sw-field">开始日期<input type="date" data-search-field="start" value="${this.searchDraft.start}"></label><label class="sw-field">结束日期<input type="date" data-search-field="end" value="${this.searchDraft.end}"></label></div><label class="sw-field">每个来源最多返回条数<input type="number" min="1" max="6" data-search-field="limit" value="${this.searchDraft.limit}"></label>${this.button(this.searchBusy?'检索公开目录中…':'查找影像','search','search','primary block',this.searchBusy?'disabled':'')}<div class="sw-notice">${icon('info')}只访问已登记固定源。目录检索不证明影像无云、可读或可用于当前算法。</div>${this.searches.length?`<label class="sw-field sw-history-select">历史目录请求<select id="sw-search-history"><option value="">选择历史检索…</option>${this.searches.map(s=>`<option value="${esc(s.id)}">${stamp(s.created_at)} · ${s.status}</option>`).join('')}</select></label>`:''}</section><section class="sw-results-panel">${this.searchResults()}</section></div>`}
 searchResults(){const r=this.searchResult;if(this.searchBusy)return '<div class="sw-working"><span class="mc-spinner"></span><h3>正在连接公开 STAC 目录</h3><p>各来源独立查询，真实失败会分别保留。不会生成替代影像记录。</p></div>';if(!r)return `<div class="sw-empty sw-large-empty">${icon('search')}<h3>先确定来源、范围与时间。</h3><p>实际命中的场景与失败记录会在这里显示。</p></div>`;const total=(r.results||[]).reduce((n,s)=>n+(s.items?.length||0),0);return `<div class="sw-results-heading"><div><span class="sw-eyebrow">CATALOG DISCOVERY ONLY</span><h2>${total} 条目录记录</h2><p>${stamp(r.created_at)} · ${r.status==='completed'?'请求完成':r.status==='partial'?'部分来源返回失败':'请求失败'}</p></div><div class="sw-ingest-actions"><span class="sw-source-type">未读取像素</span>${total?this.button(this.ingestBusy?'正在入库…':this.ingestedSearches.has(r.id)?'再次同步入库':'入库本次命中','ingest-search','data','primary',this.ingestBusy?'disabled':''):''}</div></div><div class="sw-query-summary">范围 ${fmtBounds(r.query?.bbox)}<br>时间 ${esc(r.query?.start||'—')} 至 ${esc(r.query?.end||'—')}</div>${(r.results||[]).map(s=>`<section class="sw-search-source"><div><h3>${esc(this.name(s.source_id))}</h3><span class="sw-request-status ${s.status}">${s.status==='succeeded'?'目录已检索':s.status==='empty'?'没有命中':'实际请求失败'}</span></div>${s.message?`<p class="sw-search-message">${esc(s.message)}</p>`:''}${(s.items||[]).map((it,i)=>`<button class="sw-scene-row" data-sw-action="scene" data-source="${esc(s.source_id)}" data-index="${i}"><span>${icon('layers')}</span><span><b>${esc(it.id)}</b><small>${esc(it.datetime||'未提供时间')} · ${esc(Array.isArray(it.platform)?it.platform.join(' / '):it.platform||'平台未提供')}</small></span><em>云量 ${typeof it.cloud_cover==='number'?it.cloud_cover.toFixed(1)+'%':'不适用 / 未提供'}</em></button>`).join('')}<details class="sw-technical"><summary>请求来源与追溯</summary><pre>${esc(JSON.stringify(s.provenance||{},null,2))}</pre></details></section>`).join('')}`}
 planView(){return `<div class="sw-work-layout"><section class="sw-config-panel"><h2>数据选源</h2><p>形成候选来源、推荐理由、处理步骤与缺口。此操作只生成计划，不执行新分析。</p><label class="sw-field">业务问题<textarea data-plan-field="question">${esc(this.planDraft.question)}</textarea></label><details class="sw-plan-options"><summary>补充计划条件（可选）</summary><div><label class="sw-field">区域名称<input data-plan-field="region" value="${esc(this.planDraft.region)}" placeholder="优先从问题识别"></label><label class="sw-field">空间范围 bbox<input data-plan-field="bbox" value="${esc(this.planDraft.bbox)}" placeholder="西,南,东,北"></label><div class="sw-two-fields"><label class="sw-field">开始日期<input type="date" data-plan-field="start" value="${this.planDraft.start}"></label><label class="sw-field">结束日期<input type="date" data-plan-field="end" value="${this.planDraft.end}"></label></div><label class="sw-field">业务目标<select data-plan-field="goal"><option value="">从问题自动识别</option>${[['cropland_area','耕地分类面积'],['vegetation_change','两期光谱变化'],['ndvi','单期光谱指数'],['weather','气象模型'],['flood_extent','淹没范围'],['general_discovery','一般数据发现']].map(([id,n])=>`<option value="${id}" ${this.planDraft.goal===id?'selected':''}>${n}</option>`).join('')}</select></label></div></details>${this.button(this.planBusy?'正在生成选源计划…':'生成选源计划','plan','spark','primary block',this.planBusy?'disabled':'')}<div class="sw-notice">${icon('info')}“可执行”表示存在已实现适配且条件满足，不代表本次已经运行。</div>${this.plans.length?`<label class="sw-field sw-history-select">历史计划<select id="sw-plan-history"><option value="">选择历史计划…</option>${this.plans.map(p=>`<option value="${esc(p.id)}" ${this.plan?.id===p.id?'selected':''}>${stamp(p.created_at)} · ${esc(p.request?.question?.slice(0,24)||p.interpreted?.goal||p.id)}</option>`).join('')}</select></label>`:''}</section><section class="sw-results-panel">${this.planBusy?'<div class="sw-working"><span class="mc-spinner"></span><h3>正在匹配来源与实现边界</h3><p>结合覆盖、时相、业务语义与现有适配能力。</p></div>':this.plan?this.planResult(this.plan):'<div class="sw-empty sw-large-empty">'+icon('spark')+'<h3>让目标先于数据选择。</h3><p>例如：2026年度仙桃植被变化，需要哪些数据与条件？</p></div>'}</section></div>`}
 name(id){return this.sources.find(s=>s.id===id)?.name||id}
 planResult(p,{compact=false}={}){const used=p.used||[],selected=p.selection||[],evidence=p.execution_evidence,lineage=p.provenance?.purpose==='lineage_only',archived=lineage&&evidence?.status==='succeeded'&&used.length>0;return `<div class="sw-plan-result ${compact?'compact-evidence':''}"><div class="sw-results-heading"><div><span class="sw-eyebrow">DATA SOURCE SELECTION PLAN</span><h2>${compact?'本次数据依据':'选源计划与实现边界'}</h2><p>${stamp(p.created_at)} · ${lineage?'来源归档，未发起新分析':'计划服务未执行新分析'}</p></div><span class="sw-request-status ${archived||p.executable?'succeeded':'empty'}">${lineage?(archived?'已归档实际来源':'关联历史不匹配'):(p.executable?'有可用执行适配':'需补充条件')}</span></div>${p.request?.question?`<div class="sw-plan-question">${esc(p.request.question)}</div>`:''}<section class="sw-plan-evidence"><div class="sw-subsection-title"><h3>实际使用</h3><span>以已完成任务来源记录为准</span></div>${used.length?`<div class="sw-used-sources">${used.map(s=>`<article><span class="sw-used-mark">${icon('check')}</span><div><b>${esc(this.name(s.source_id||s.id||s))}</b><p>${s.evidence?.year?esc(s.evidence.year)+'年 · ':''}${esc(s.reason||({actual_input:'实际数据输入',actual_mask:'实际市界掩膜'}[s.role])||s.role||'已与真实成功任务绑定')}</p></div><span>任务证据</span></article>`).join('')}</div><p class="sw-evidence-id">${esc(({landcover:'全市核算',production:'像元分析'}[evidence?.task_type])||evidence?.task_type||'')} · ${esc(evidence?.task_id||'')} · ${evidence?.status==='succeeded'?'已完成':esc(evidence?.status||'')}</p>`:'<div class="sw-plan-empty">本计划未关联真实成功任务，没有可声称为“已使用”的数据。</div>'}</section><section class="sw-plan-selection"><div class="sw-subsection-title"><h3>方案推荐</h3><span>尚未执行 · 不代表已取得数据</span></div>${selected.map(s=>this.selectionCard(s)).join('')||`<div class="sw-plan-empty">${lineage?'此记录仅归档实际来源，未生成新的选源方案。':'当前条件不足以形成推荐来源。'}</div>`}</section>${(p.gaps||[]).length?`<section class="sw-plan-gaps"><h3>缺口与待确认事项</h3>${p.gaps.map(g=>`<div class="${g.severity==='blocking'?'blocking':''}"><span>${g.severity==='blocking'?'阻塞条件':'需关注'}</span><p>${esc(g.message)}</p></div>`).join('')}</section>`:''}${!compact?`<details class="sw-candidates"><summary>全部候选来源与推荐理由</summary>${(p.candidates||[]).map(c=>`<div><b>${esc(this.name(c.source_id))}</b><p>${esc(c.reason)}</p><span>${esc(c.suitability||'候选')}</span></div>`).join('')}</details><details class="sw-technical"><summary>计划步骤与执行契约</summary><div class="sw-plan-steps">${(p.steps||[]).map(s=>`<div><span>${s.status==='blocked'?'待条件满足':'计划步骤'}</span><b>${esc(operationLabel(s.operation))}</b><small>${esc(this.name(s.source_id))}</small></div>`).join('')}</div><pre>${esc(JSON.stringify({not_executed:p.not_executed,execution_contract:p.execution_contract,catalog_fingerprint:p.catalog_fingerprint,source_snapshot:p.source_snapshot,provenance:p.provenance},null,2))}</pre></details>`:''}</div>`}
 selectionCard(s){return `<article class="sw-selected-source"><div><b>${esc(this.name(s.source_id))}</b><span>${esc(({primary:'主数据',mask:'范围掩膜',reference:'参考数据',actual_input:'实际输入',actual_mask:'实际掩膜'}[s.role]||s.role||'拟议来源'))}</span></div><p>${esc(s.reason)}</p><div class="sw-operation-tags">${(s.operations||[]).map(o=>`<span>${esc(operationLabel(o))}</span>`).join('')}</div>${s.stages?`<small>目录 ${s.stages.catalog_searchable?'有检索适配':'未接'} · 像素 ${s.stages.pixel_applicable===false?'不适用':s.stages.pixel_readable?'有读取适配':'像素未接'} · 分析 ${s.stages.analysis_ready?'有执行适配':'未接'}</small>`:''}</article>`}
 mountLibrary(){if(!this.library){this.library=new ObservationLibrary({api:this.api,toast:this.toast,showDialog:this.showDialog,sources:this.sources,onPrepareAnalysis:this.onPrepareAnalysis,onMap:this.onObservationMap});this.library.onDiscover=()=>{this.tab='search';this.render()}}this.library.sources=this.sources;const host=this.element.querySelector('#sw-observation-library');if(host)this.library.mount(host)}
 async ingestSearch(){if(this.ingestBusy||!this.searchResult?.id)return;this.ingestBusy=true;this.render();try{const r=await this.api('/observations/ingest',{method:'POST',body:{search_id:this.searchResult.id}});this.ingestedSearches.add(this.searchResult.id);if(this.library)this.library.ready=false;this.tab='library';this.toast('入库完成'+(Number.isFinite(r.inserted)?' · 新增'+r.inserted+'条':'')+(Number.isFinite(r.updated)?'，更新'+r.updated+'条':''))}finally{this.ingestBusy=false;this.render()}}
 async search(){if(this.searchBusy)return;if(!this.searchDraft.source_ids.length)throw Error('至少选择一个已实现的目录来源');if(this.searchDraft.source_ids.length>7)throw Error('一次最多选择7个目录来源');const bbox=this.parseBBox(this.searchDraft.bbox);if(!this.searchDraft.start||!this.searchDraft.end)throw Error('请填写完整检索日期');this.searchBusy=true;this.searchResult=null;this.error='';this.render();try{const r=await this.api('/data-sources/search',{method:'POST',body:{source_ids:this.searchDraft.source_ids,bbox,start:this.searchDraft.start,end:this.searchDraft.end,limit:Number(this.searchDraft.limit)}});this.searchResult=r;this.searches=[r,...this.searches.filter(s=>s.id!==r.id)];this.toast(r.status==='failed'?'公开目录请求失败，未生成替代记录':r.status==='partial'?'部分来源未返回，实际结果已保留':'目录请求已完成，尚未读取像素')}catch(e){this.error=e.message;this.toast(e.message)}finally{this.searchBusy=false;this.render()}}
 parseBBox(v){const bbox=String(v).trim().split(/[,，\s]+/).map(Number);if(bbox.length!==4||bbox.some(n=>!Number.isFinite(n))||bbox[0]>=bbox[2]||bbox[1]>=bbox[3])throw Error('范围需按西、南、东、北填写四个有效坐标');return bbox}
 async createPlan(){if(this.planBusy)return;const q=this.planDraft.question.trim();if(!q)throw Error('请先描述业务问题');const body={question:q};if(this.planDraft.region.trim())body.region=this.planDraft.region.trim();if(this.planDraft.bbox.trim())body.bbox=this.parseBBox(this.planDraft.bbox);if(this.planDraft.goal)body.goal=this.planDraft.goal;if(this.planDraft.start||this.planDraft.end){if(!this.planDraft.start||!this.planDraft.end)throw Error('请完整填写起止日期');body.period={start:this.planDraft.start,end:this.planDraft.end}}this.planBusy=true;this.plan=null;this.error='';this.render();try{const p=await this.api('/data-plans',{method:'POST',body});this.plan=p;this.plans=[p,...this.plans.filter(x=>x.id!==p.id)];this.toast('选源计划已生成；尚未执行新分析')}catch(e){this.error=e.message;this.toast(e.message)}finally{this.planBusy=false;this.render()}}
 async loadTianditu(render=true){try{this.tianditu=await this.api('/integrations/tianditu')}catch(e){this.tianditu={configured:false,status:'unavailable',message:'配置状态暂未读取：'+e.message}}if(render)this.render();return this.tianditu}
 tiandituLabel(){const t=this.tianditu;if(!t)return'正在读取状态';return({not_configured:'待配置',configured:'已配置 · 待验证',verified:'验证通过',partial:'部分服务可用',failed:'验证未通过',restricted:'调用受限',unavailable:'状态待刷新'}[t.status]||(t.configured?'已配置 · 待验证':'待配置'))}
 tiandituServices(){const services=this.tianditu?.services||{};return [['tiles','影像与矢量底图'],['search','地名地址检索'],['reverse','坐标地址查询'],['administrative','行政区参考范围']].map(([id,label])=>{const v=services[id];return `<span class="${v?.status==='verified'||v?.status==='available'||v?.status==='succeeded'?'verified':''}">${icon(v?.status==='verified'||v?.status==='available'||v?.status==='succeeded'?'check':'clock')}${label}<small>${esc(({verified:'验证通过',available:'验证通过',succeeded:'验证通过',failed:'验证未通过',restricted:'调用受限',not_configured:'待配置',configured:'待验证',not_checked:'待验证'}[v?.status])||(this.tianditu?.configured?'待验证':this.tianditu?'待配置':'待读取'))}</small></span>`}).join('')}
 tiandituCard(){const t=this.tianditu;return `<section class="sw-tdt-card" aria-label="天地图地图服务"><div class="sw-tdt-heading"><span class="sw-tdt-mark">天</span><div><h2>天地图 <small>国家地理信息公共服务平台</small></h2><p>影像、矢量底图与中文注记；地名、地址及兴趣点检索。</p></div><span class="sw-tdt-status ${esc(t?.status||'loading')}">${esc(this.tiandituLabel())}</span></div><div class="sw-tdt-services">${this.tiandituServices()}</div><div class="sw-tdt-footer"><p>${esc(t?.message||'正在读取本机服务配置。')}${t?.checked_at?' · 最近验证 '+stamp(t.checked_at):''}</p>${this.button(t?.configured?'管理与验证':'配置天地图','tianditu-config','data',t?.configured?'':'primary')}</div><small class="sw-tdt-boundary">底图用于定位与展示；遥感指数仍读取可计算波段。检索位置不作为行政统计边界。</small>${this.administrativeView()}</section>`}
 administrativeView(){return `<details class="sw-tdt-admin" ${this.adminQuery||this.adminBusy?'open':''}><summary>查询行政区参考范围</summary><p>按名称查询并选择行政区候选；仅有真实边界返回时可上图和下载。</p><div class="sw-tdt-admin-query"><label class="sr-only" for="sw-tdt-admin-query">行政区名称</label><input id="sw-tdt-admin-query" data-tdt-admin-query autocomplete="off" placeholder="例如：仙桃市" value="${esc(this.adminQuery)}"><button class="sw-button" data-sw-action="tianditu-administrative" ${!this.tianditu?.configured||this.adminBusy?'disabled':''}>${icon('search')}${this.adminBusy?'查询中…':'查询范围'}</button></div>${!this.tianditu?.configured?'<small>请先配置天地图服务端 Key。</small>':''}${this.adminSuggestions?.length?`<div class="sw-tdt-suggestions"><small>可尝试以下完整名称：</small>${this.adminSuggestions.map(v=>`<button data-sw-action="tianditu-administrative-suggestion" data-value="${esc(v)}">${esc(v)}</button>`).join('')}</div>`:''}${this.adminError?`<p class="sw-tdt-admin-error" role="alert">${esc(this.adminError)}</p>`:''}<div class="sw-tdt-admin-results">${this.adminResults.map((r,i)=>`<article><div><b>${esc(r.name)}</b><small>${esc(r.code||'编码未提供')} · ${esc(r.level||'行政参考范围')}</small><p>${esc(r.message||'天地图公开行政参考边界；非确权、耕地或法定调查范围。')}</p></div><div>${this.button('地图查看','tianditu-boundary-map','layers','',r.geojson?`data-index="${i}"`:'disabled')}${this.button('下载范围','tianditu-boundary-download','data','',r.geojson?`data-index="${i}"`:'disabled')}</div></article>`).join('')}</div><small>查看范围生成临时参考图层，不会自动更改专题分析范围或替换历史统计边界。</small></details>`}
 async queryAdministrative(b){if(this.adminBusy)return;const input=b.closest('.sw-tdt-card')?.querySelector('[data-tdt-admin-query]');this.adminQuery=input?.value.trim()||'';if(!this.adminQuery)throw Error('请填写行政区名称');if(!this.tianditu?.configured)throw Error('请先配置天地图服务端 Key');this.adminBusy=true;this.adminError='';this.adminResults=[];this.adminSuggestions=[];this.refreshTiandituCards();try{const result=await this.api('/tianditu/administrative?keyword='+encodeURIComponent(this.adminQuery));this.adminResults=result.results||[];this.adminSuggestions=result.suggestions||[];this.adminError=(result.warnings||[]).map(w=>typeof w==='string'?w:w.message||'').filter(Boolean).join('；');if(!this.adminResults.length&&!this.adminSuggestions.length&&!this.adminError)this.adminError='没有找到行政区候选，请使用完整名称重试。'}catch(e){this.adminError=e.message}finally{this.adminBusy=false;this.refreshTiandituCards()}}
 refreshTiandituCards(){this.render();const card=document.querySelector('#dialog .sw-tdt-card');if(card)card.outerHTML=this.tiandituCard()}
 downloadAdministrative(r){if(!r?.geojson?.features)throw Error('该候选未返回可下载的真实边界');const geo={...r.geojson,metadata:{...(r.geojson.metadata||{}),source:r.source||'天地图行政区划服务',source_url:r.source_url,usage:'公开行政参考边界；非确权、耕地或法定调查范围'}};const href=URL.createObjectURL(new Blob([JSON.stringify(geo,null,2)],{type:'application/geo+json'})),a=document.createElement('a');a.href=href;a.download=String(r.name||'行政区')+'-天地图参考范围.geojson';a.click();setTimeout(()=>URL.revokeObjectURL(href),1000)}
 async showTianditu(){await this.loadTianditu(false);this.renderTiandituDialog()}
 renderTiandituDialog(){const t=this.tianditu||{},env=t.key_source==='environment'||t.credential_source==='environment'||t.token_source==='environment';this.showDialog('天地图服务配置',`<p>申请允许服务端调用的应用 Key。密钥保存在本机服务端，不会下发到地图链接或浏览器存储。</p><ol class="sw-tdt-steps"><li>登录天地图控制台，申请允许服务端调用的应用 Key。</li><li>如设置 IP 限制，请授权部署服务的出口 IP。</li><li>在下方保存并验证，随后可在地图切换底图、按回车检索地址。</li></ol><div class="sw-tdt-dialog-status"><b>${esc(this.tiandituLabel())}</b><p>${esc(t.message||'尚未配置服务。')}</p>${t.checked_at?`<small>最近验证 ${stamp(t.checked_at)}</small>`:''}</div><div class="sw-tdt-services">${this.tiandituServices()}</div><label class="field">${t.configured?'更新应用 Key（不回显已有密钥）':'应用 Key（允许服务端调用）'}<input id="sw-tdt-token" type="password" autocomplete="new-password" spellcheck="false" autocapitalize="off" placeholder="填写您申请的 Key" aria-describedby="sw-tdt-key-note" ${env?'disabled':''}></label><p id="sw-tdt-key-note" class="sw-tdt-key-note">${env?'当前使用环境变量配置，请在服务端环境修改。':'仅提交给当前本机服务；不需要在聊天中发送密钥。保存后会发起实际服务验证。'}</p><div class="sw-tdt-links"><a href="https://lbs.tianditu.gov.cn/server/MapService.html" target="_blank" rel="noopener noreferrer">查看官方服务文档 ↗</a><a href="${esc(url(t.apply_url)||'https://cloudcenter.tianditu.gov.cn/center/development/myApp')}" target="_blank" rel="noopener noreferrer">申请 / 管理 Key ↗</a></div><div class="sw-notice">${icon('info')}影像与注记为地图瓦片；POI、地址和坐标定位不代表可用于面积统计的行政边界。服务可用性、配额与授权以天地图实际响应为准。</div>`,`${!env?this.button('保存并验证','tianditu-save','check','primary'):''}${this.button('验证已有配置','tianditu-check','refresh','',t.configured?'':'disabled')}${this.button('清除本机配置','tianditu-clear','data','',t.configured&&!env?'':'disabled')}`)}
 async runTianditu(action){const input=document.querySelector('#sw-tdt-token'),dialog=document.querySelector('#dialog');const buttons=[...(dialog?.querySelectorAll('[data-sw-action^="tianditu-"]')||[])];buttons.forEach(b=>b.disabled=true);try{if(action==='save'){const token=input?.value.trim();if(!token)throw Error('请填写天地图服务端应用 Key');await this.api('/integrations/tianditu',{method:'POST',body:{token}});input.value='';this.tianditu=await this.api('/integrations/tianditu/check',{method:'POST',body:{}})}else if(action==='clear'){this.tianditu=await this.api('/integrations/tianditu',{method:'POST',body:{action:'clear'}})}else this.tianditu=await this.api('/integrations/tianditu/check',{method:'POST',body:{}});await this.onIntegrationChange?.(this.tianditu);this.render();this.renderTiandituDialog();this.toast(action==='clear'?'已清除本机天地图配置':this.tianditu.message||'天地图配置状态已更新')}catch(e){if(input)input.value='';await this.loadTianditu(false);this.renderTiandituDialog();throw e}finally{buttons.forEach(b=>{if(b.isConnected)b.disabled=false})}}
 async ensureCatalog(){if(!this.sources.length){const c=await this.api('/data-sources');this.sources=c.sources||[]}}
 async showEvidence(id){await this.ensureCatalog();const p=await this.api('/data-plans/'+encodeURIComponent(id));this.plan=p;this.tab='plans';this.showDialog('本次数据依据与后续缺口',this.planResult(p,{compact:true})+'<div class="sw-readonly-note">实际使用仅由成功任务来源证据支持；推荐来源仍是计划，不代表已接入或已执行。</div><button class="sw-readonly-professional" data-action="open-sources">在专业工作台查看完整方案 →</button>')}
 async showCoverage(){await Promise.all([this.ensureCatalog(),this.loadTianditu(false)]);this.showDialog('数据接入与覆盖',`<p>数据源已统一编目，实现阶段各不相同。下列状态是适配能力说明，不代表本次分析已使用全部来源。</p>${this.tiandituCard()}<div class="sw-readonly-sources">${this.sources.filter(s=>!s.id.startsWith('draft_')).map(s=>`<article><div><b>${esc(s.name)}</b><span>${esc(stageText(s.stages?.connection_status))}</span></div><p>${s.coverage?.temporal?.product_year?esc(s.coverage.temporal.product_year)+' 固定年度 · ':''}${esc(s.resolution?.description||s.resolution?.native||'覆盖详见来源')}</p><small>${s.stages?.catalog_searchable?'目录可检索':'目录未接 / 不适用'} · ${this.raster(s)?s.stages?.pixel_readable?'具备像素读取':'像素未接':'非栅格数据'} · ${s.stages?.analysis_ready?'已有分析适配':'暂无算法接入'}</small></article>`).join('')}</div><div class="sw-readonly-note">政务、高分、无人机与物联网等资源需完成授权和接口对接后，才能成为可调用能力。</div><button class="sw-readonly-professional" data-action="open-sources">在专业工作台查看多源目录 →</button>`)}
 async detail(id){const s=await this.api('/data-sources/'+encodeURIComponent(id));this.showDialog(esc(s.name),`<div class="sw-detail-provider">${esc(s.provider)} · ${esc(s.protocol)}</div>${this.stages(s)}<div class="dialog-rows">${[['空间覆盖',fmtBounds(s.coverage?.spatial?.bbox)],['时间覆盖',s.coverage?.temporal?.product_year?String(s.coverage.temporal.product_year)+'固定年度':(s.coverage?.temporal?.start||'未提供')+' / '+(s.coverage?.temporal?.end||'持续 / 未提供')],['分辨率',s.resolution?.description||s.resolution?.native],['波段或属性',(s.bands||[]).join(' / ')],['数据许可',s.license?.name],['服务费用/约束',s.cost?.note||s.cost?.model],['授权方式',this.authText(s)],['适配器版本',s.adapter?.id+' / '+s.adapter?.version],['元数据核查时间',s.provenance?.verified_at||'未提供；不声称近期验证成功']].map(([k,v])=>`<div class="dialog-row"><span>${k}</span><span>${esc(text(v))}</span></div>`).join('')}</div><h3 class="pw-report-h3">能力与适用边界</h3><ul class="dialog-list">${(s.limitations||[]).map(l=>`<li>${esc(l)}</li>`).join('')}</ul>${url(s.license?.url)?`<a class="sw-source-link" href="${esc(url(s.license.url))}" target="_blank" rel="noopener">查看提供方许可条款 ↗</a>`:''}${url(s.provenance?.source_url)?`<a class="sw-source-link" href="${esc(url(s.provenance.source_url))}" target="_blank" rel="noopener">查看原始来源说明 ↗</a>`:''}`)}
 draftDialog(){this.showDialog('登记数据接入草案',`<p>仅登记接口意向，不访问地址、不保存密钥，也不会显示为“已连接”。</p><label class="field">来源名称<input id="sw-draft-name" maxlength="100" placeholder="例如：市级农业台账服务"></label><label class="field">来源类型<select id="sw-draft-type"><option value="ogc">OGC空间服务</option><option value="business">业务系统</option><option value="iot">物联网</option><option value="catalog">数据目录</option></select></label><label class="field">服务地址<input id="sw-draft-endpoint" placeholder="https://example.gov.cn/service"></label><label class="field">协议<input id="sw-draft-protocol" value="REST API"></label><div class="notice">不要在地址中填写token、密码或其他凭据。正式对接需服务端授权、许可及连通性验证。</div><div class="dialog-actions">${this.button('保存为未连接草案','save-draft','plus','primary')}</div>`)}
 async saveDraft(){const name=document.querySelector('#sw-draft-name')?.value.trim(),endpoint=document.querySelector('#sw-draft-endpoint')?.value.trim(),source_type=document.querySelector('#sw-draft-type')?.value,protocol=document.querySelector('#sw-draft-protocol')?.value.trim();if(!name||!endpoint||!protocol)throw Error('请完整填写草案名称、地址和协议');await this.api('/data-sources/drafts',{method:'POST',body:{name,source_type,endpoint,protocol}});document.querySelector('#dialog')?.close();await this.load();this.toast('草案已登记；尚未连接或验证服务')}
 async act(a,b){switch(a){case'ingest-search':await this.ingestSearch();break;case'tianditu-administrative-suggestion':{const input=b.closest('.sw-tdt-card')?.querySelector('[data-tdt-admin-query]');if(input)input.value=b.dataset.value;await this.queryAdministrative(b);break}case'tianditu-administrative':await this.queryAdministrative(b);break;case'tianditu-boundary-map':{const r=this.adminResults[Number(b.dataset.index)];if(!r?.geojson)throw Error('该候选未返回可上图的真实边界');await this.onBoundary?.(r);break}case'tianditu-boundary-download':this.downloadAdministrative(this.adminResults[Number(b.dataset.index)]);break;case'tianditu-config':await this.showTianditu();break;case'tianditu-save':await this.runTianditu('save');break;case'tianditu-check':await this.runTianditu('check');break;case'tianditu-clear':await this.runTianditu('clear');break;case'tab':this.tab=b.dataset.tab;this.error='';this.render();if(this.tab==='uploads')await this.refreshDatasets();break;case'filter':this.filter=b.dataset.filter;this.render();break;case'detail':await this.detail(b.dataset.id);break;case'reload':await this.load();break;case'search':await this.search();break;case'plan':await this.createPlan();break;case'datasets':this.tab='uploads';this.render();await this.refreshDatasets();break;case'upload':if(!this.onImport)throw Error('上传入口尚未就绪，请刷新重试');await this.onImport();break;case'dataset-map':if(!this.onDatasetMap)throw Error('地图尚未就绪，请刷新重试');await this.onDatasetMap(b.dataset.id);break;case'dataset-detail':await this.datasetDetail(b.dataset.id);break;case'reload-uploads':await this.refreshDatasets();break;case'draft':this.draftDialog();break;case'save-draft':await this.saveDraft();break;case'scene':{const r=this.searchResult.results.find(r=>r.source_id===b.dataset.source),it=r?.items?.[Number(b.dataset.index)];if(it)this.showDialog('目录元数据记录',`<p>仅检索到目录记录，尚未读取像素或执行算法。</p><div class="dialog-rows">${Object.entries(it).map(([k,v])=>`<div class="dialog-row"><span>${esc(k)}</span><span>${esc(text(v))}</span></div>`).join('')}</div>`);break}}}
}
